import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
f=np.load('/app/output/fk_fit.npz');x=f['x'];sgn=f['sgn'];qcur=np.load('/app/output/stage_jac.npz')['q'][:7]
lo=np.array([-2.967,-2.094,-2.967,-2.094,-2.967,-2.094,-3.054]);hi=-lo

def fk(q):
 R=Rotation.from_euler('z',x[3]).as_matrix();p=x[:3].copy()
 for j in range(7):
  ax=np.array([0.,0.,1.]) if j%2==0 else np.array([0.,1.,0.])
  R=R@Rotation.from_rotvec(ax*q[j]*sgn[j]).as_matrix();p+=R@np.array([0.,0.,x[4+j]])
 return p+R@x[11:14]
for target in [[.12,.36,.17],[.17,.32,.24],[.15,.34,.3]]:
 best=None
 for k in range(60):
  if k==0:q0=qcur.copy()
  elif k<20:q0=np.clip(qcur+np.random.randn(7)*.5,lo+.01,hi-.01)
  else:q0=np.random.uniform(lo,hi)
  def fun(q):return np.r_[10*(fk(q)-target),.08*(q-qcur)]
  r=least_squares(fun,q0,bounds=(lo,hi),max_nfev=200)
  err=np.linalg.norm(fk(r.x)-target)
  if best is None or err<best[0]:best=(err,r.x)
